// Fun facts for the geography cards. GENERATED by scripts/build-geo-facts.mjs
// (Wikipedia text → Haiku draft → verbatim-quote check → Sonnet fact-check).
// Edit geo-facts.json + rerun scripts/geo-facts-to-ts.mjs, or edit entries here
// directly. Never add a fact you can't source.
export const GEO_FACTS: Record<string, string> = {};

export function geoFact(kind: "state" | "country", name: string): string | undefined {
  return GEO_FACTS[`${kind}:${name}`];
}
